// Extract issue key, summary, and description text.
// Handles multiple possible shapes depending on Jira node settings:
// 1) simplifyOutput=true -> capitalized display keys directly on the item (Summary, Description)
// 2) raw Jira API shape -> nested under fields.summary / fields.description
// 3) description may be plain text OR Atlassian Document Format (ADF) JSON
const issue = $input.item.json;

const issueKey = issue.key || issue.id || 'UNKNOWN';
const summary = issue.Summary ?? issue.fields?.summary ?? issue.summary ?? '';

let rawDescription;
if (issue.Description !== undefined) {
  rawDescription = issue.Description;
} else if (issue.fields?.description !== undefined) {
  rawDescription = issue.fields.description;
} else {
  rawDescription = issue.description;
}

function adfToText(node) {
  if (!node) return '';
  if (typeof node === 'string') return node;
  let text = '';
  if (node.type === 'text' && node.text) {
    text += node.text;
  }
  if (Array.isArray(node.content)) {
    for (const child of node.content) {
      text += adfToText(child);
      if (child.type === 'paragraph' || child.type === 'listItem' || child.type === 'heading') {
        text += '\n';
      }
    }
  }
  return text;
}

let descriptionText = '';
if (!rawDescription) {
  descriptionText = '(No description provided)';
} else if (typeof rawDescription === 'string') {
  descriptionText = rawDescription;
} else if (typeof rawDescription === 'object') {
  // Likely ADF (Atlassian Document Format)
  descriptionText = adfToText(rawDescription).trim();
  if (!descriptionText) {
    descriptionText = '(Description present but could not be parsed from ADF format)';
  }
}

const formattedStory = `Story: ${issueKey} - ${summary}\n\n${descriptionText}`;

return [{
  json: {
    issueKey,
    summary,
    formattedStory
  }
}];

parameters.text:
=Analyze the following User Story and its Acceptance Criteria, then generate functional test cases.

User Story:
{{ $json.formattedStory }}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "decision": {
      "type": "string",
      "enum": ["Approve", "Denied"]
    },
    "reason": {
      "type": "string",
      "description": "Explanation of the decision. Required detail when Denied; can be a short confirmation note when Approved."
    },
    "testCases": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": { "type": "string" },
          "title": { "type": "string" },
          "type": { "type": "string", "enum": ["Positive", "Negative", "Edge Case"] },
          "priority": { "type": "string", "enum": ["High", "Medium", "Low"] },
          "preconditions": { "type": "string" },
          "steps": { "type": "string" },
          "expectedResult": { "type": "string" },
          "dataNeeded": { "type": "string" }
        },
        "required": ["id", "title", "type", "priority", "preconditions", "steps", "expectedResult", "dataNeeded"]
      }
    }
  },
  "required": ["decision", "reason", "testCases"]
}

parameters.text:
=Based on the test cases below, generate specific test data for each one that needs it.

Original Story / Acceptance Criteria:
{{ $('Format Jira Story Text').item.json.formattedStory }}

Test Cases (JSON):
{{ JSON.stringify($json.output.testCases) }}

parameters.jsCode:
const storyInfo = $('Format Jira Story Text').item.json;
const review = $('AI Test Case Generator').item.json.output;
const dataOut = $input.item.json.output;

const testCases = review.testCases || [];
const testData = dataOut.testData || [];
const dataByCaseId = {};
for (const td of testData) {
  dataByCaseId[td.testCaseId] = td.fields;
}

let md = `**Jira Issue:** ${storyInfo.issueKey} - ${storyInfo.summary}\n\n`;

if (review.decision === 'Denied') {
  md += `**Decision:** Denied\n\n**Reason:** ${review.reason}\n\nNo test cases or test data were generated. Please update the Jira story's acceptance criteria and retry.\n`;
} else {
  md += `**Decision:** Approve\n\n## Test Cases\n\n`;
  for (const tc of testCases) {
    md += `### [${tc.id}] ${tc.title} (${tc.type} / ${tc.priority})\n`;
    md += `**Preconditions:** ${tc.preconditions}\n\n`;
    md += `**Steps:** ${tc.steps}\n\n`;
    md += `**Expected Result:** ${tc.expectedResult}\n\n`;
    md += `**Data Needed:** ${tc.dataNeeded}\n\n`;

    const fields = dataByCaseId[tc.id];
    if (fields && fields.length > 0) {
      md += `**Test Data:**\n`;
      for (const f of fields) {
        if (f.valid && f.valid.length) md += `- ${f.fieldName} (valid): ${f.valid.join(', ')}\n`;
        if (f.invalid && f.invalid.length) md += `- ${f.fieldName} (invalid): ${f.invalid.join(', ')}\n`;
        if (f.boundaryEdge && f.boundaryEdge.length) md += `- ${f.fieldName} (boundary/edge): ${f.boundaryEdge.join(', ')}\n`;
      }
    }
    md += `\n`;
  }
}

return [{
  json: {
    output: md,
    issueKey: storyInfo.issueKey,
    decision: review.decision,
    reason: review.reason,
    testCases,
    testData
  }
}];
